export function hamptonLeaseChargesWorkbook(): Buffer {
  const cover = utils.aoa_to_sheet([
    ["Hampton Gardens"],
    ["Cover — do not import this tab"],
  ]);
  const rr = utils.aoa_to_sheet(hamptonLeaseChargesRows());
  const wb = utils.book_new();
  utils.book_append_sheet(wb, cover, "Cover");
  utils.book_append_sheet(wb, rr, "Rent Roll with Lease Charges");
  return Buffer.from(write(wb, { type: "buffer", bookType: "xlsx" }));
}
